const findLabel = (map, id) => {
    if (!map || !id) return null;
    const item = map.find(i => i.Id === id || i.value === id);
    return item ? (item.label || item.Name || item.DisplayName) : null;
};

const tax = findLabel($ctrl.referenceData.taxMap, f.TaxIdd) || "Tax";
const country = findLabel($ctrl.referenceData.countryMap, f.CountryId) || "Country";
const state = f.StateId ? findLabel($ctrl.referenceData.stateMap[f.CountryId], f.StateId) : null;

return `${tax} - ${country}${state ? ` (${state})` : ''}`;

if (!params) params = {};

const currentTabName = $ctrl.uiState.currentTab.name;

// Default values
const {
    entityType = currentTabName,
    page = $ctrl.tabStore[currentTabName].currentPage,
    query = $ctrl.uiState.currentFilter.currentFilterString,
    isAfterWrite = false
} = params;

const isTaxRelated = ["tax", "tax_schedule", "tax_applicability"].includes(entityType);

let apiQuery = $ctrl.filterService.buildCombinedQuery({
    // quickSearchConfig: $ctrl.tabConfig[entityType].quickSearchDefaultConfig,
    // quickSearchValue: query,
    advancedFilters: $ctrl.uiState.currentFilter.advancedFilters
});

if ($ctrl.tabConfig[entityType]?.companyBound) apiQuery += `&CompanyId=${$ctrl.globalSelectedCompany.companyId}`;

await $ctrl.baseGridControllerService.loadGridData($ctrl, {
    entityType,
    customEntityKey: $ctrl.tabConfig[entityType]?.customEntityKey,
    columnDefs: $ctrl.tabConfig[entityType].columnDefaultConfig,
    page,
    limit: $ctrl.tabStore[entityType].limit,
    query: apiQuery,
    hydrateOnLoad: isTaxRelated
});

$ctrl.loaders.loadReferenceMaps({ isAfterWrite });

try {
    if (!params) params = {};

    const { isAfterWrite } = params;

    if (isAfterWrite) {
        $ctrl.referenceDataService.clearCache();
    }

    const companyOpts = await $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Company");

    if ($ctrl.globalSelectedCompany) {
        $ctrl.globalSelectedCompany.companyMap = companyOpts;
        $ctrl.globalSelectedCompany.setMenuItems();
    }

    // Fetch formatted options directly from service
    const [currencyOpts, countryOpts, stateOpts, accrualOpts, earningOpts, taxOpts] = await Promise.all([
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Currency"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Country"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("State"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Accrual"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Earning"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Tax"),
    ]);

    $ctrl.referenceData.companyMap = companyOpts;
    $ctrl.referenceData.currencyMap = currencyOpts;
    $ctrl.referenceData.countryMap = countryOpts;
    $ctrl.referenceData.accrualMap = accrualOpts;
    $ctrl.referenceData.earningMap = earningOpts;
    $ctrl.referenceData.taxMap = taxOpts;

    $ctrl.referenceData.stateMap = stateOpts.reduce((acc, state) => {
        if (!acc[state.CountryId]) acc[state.CountryId] = [];
        acc[state.CountryId].push(state);
        return acc;
    }, {});

} catch (e) {
    console.warn("Background reference load failed", e);
}

const componentClass = type.toUpperCase();
const idField = type === 'earning' ? 'EarningId' : 'BenefitId';

const stateRoot = $ctrl.uiState.assignments[type];
if (!stateRoot) {
    console.error(`UI State path uiState.assignments.${type} not found.`);
    return;
}

stateRoot.position.loading = true;
stateRoot.worker.loading = true;
stateRoot.position.displayed = ["Loading..."];
stateRoot.worker.displayed = ["Loading..."];

try {
    const [positionLinksRes, workerLinksRes] = await Promise.all([
        $ctrl.payrollApiService.get({
            limit: 1000,
            entity: "position_pay_component",
            query: `${idField}_eq=${targetId}`,
            customEntityKey: "positionpaycomponent"
        }),
        $ctrl.payrollApiService.get({
            limit: 1000,
            entity: "worker_pay_component",
            query: `${idField}_eq=${targetId}`,
            customEntityKey: "workerpaycomponent"
        })
    ]);

    if ($ctrl.uiState.selectedEntity?.Id !== targetId) return;

    const positionLinks = positionLinksRes?.entities ?? positionLinksRes ?? [];
    const workerLinks = workerLinksRes?.entities ?? workerLinksRes ?? [];

    const positionIds = positionLinks.map(l => l.PositionId).filter(id => id);
    const workerIds = workerLinks.map(l => l.WorkerId).filter(id => id);

    const uniquePositionIds = [...new Set(positionIds)];

    // Parallel resolution using both batch resolvers
    const [positions, users] = await Promise.all([
        $ctrl.referenceDataService.resolvers.batchResolveById("position", uniquePositionIds),
        $ctrl.referenceDataService.resolvers.batch.resolveUsersByWorkerId(workerIds)
    ]);

    const positionMap = new Map();
    (positions || []).forEach(p => { if (p) positionMap.set(String(p.Id), p); });

    const userMap = new Map();
    (users || []).forEach(u => { if (u) userMap.set(String(u.WorkerId), u); });

    const finalPositions = positionLinks.map(link => {
        const pos = positionMap.get(String(link.PositionId));
        return {
            Id: link.PositionId,
            Name: pos ? pos.Title : `Unknown Position (${link.PositionId})`,
            _linkId: link.Id,
            CustomEmployeeAmount: link.CustomEmployeeAmount,
            CustomEmployerAmount: link.CustomEmployerAmount
        };
    });

    stateRoot.position.current = finalPositions;
    stateRoot.position.original = angular.copy(finalPositions);
    stateRoot.position.displayed = finalPositions.length > 0
        ? finalPositions.map(p => p.Name)
        : [];
    stateRoot.position.loading = false;

    const finalWorkers = workerLinks.map(link => {
        const user = userMap.get(String(link.WorkerId));
        return {
            Id: link.WorkerId,
            Name: user ? `${user.FirstName} ${user.LastName}` : `Unknown Worker (${link.WorkerId})`,
            _linkId: link.Id,
            CustomEmployeeAmount: link.CustomEmployeeAmount,
            CustomEmployerAmount: link.CustomEmployerAmount
        };
    });

    stateRoot.worker.current = finalWorkers;
    stateRoot.worker.original = angular.copy(finalWorkers);
    stateRoot.worker.displayed = finalWorkers.length > 0
        ? finalWorkers.map(w => w.Name)
        : [];
    stateRoot.worker.loading = false;

} catch (err) {
    console.error("Failed to load assignments", err);
    $ctrl.utils.toast("Failed to load assignments", "ERROR");
    stateRoot.position.loading = false;
    stateRoot.worker.loading = false;
    stateRoot.position.displayed = ["Error loading data"];
    stateRoot.worker.displayed = ["Error loading data"];
}

const config = $ctrl.tabConfig[$ctrl.uiState.currentTab.name];
if (!config) {
    console.error("No configuration found for current tab:", $ctrl.uiState.currentTab.name);
    return;
}

if(config.form === "form"){
    if($ctrl.form.accrualId != null){
        $ctrl.form.code = null
    } 
    else if($ctrl.form.code != null){
        $ctrl.form.accrualId = null
    }
}

const isUpdate = $ctrl.uiState.isEditingExistingEntity;
const method = isUpdate ? "PUT" : "POST";
let formData = $ctrl[config.form];

if (config.form === "form5" && method === "PUT") {
    const { taxId: _, ...formDataWithoutTaxId } = formData;
    formData = formDataWithoutTaxId;
}

let displayName = "Item";
if (config.getName) {
    displayName = config.getName(formData);
} else if (config.entityNameKey) {
    displayName = formData[config.entityNameKey] || "Item";
}

const additionalData = {};
if (config.companyBound && method === "POST") {
    additionalData.CompanyId = $ctrl.globalSelectedCompany.companyId;
}

$ctrl.uiState.isSaving = true;

await $ctrl.entityOperationsService.executeEntityOperation(
    method,
    formData,
    async (result) => { // onSuccess
        // Reload Grid
        if (method === "POST") {
            $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
            $ctrl.formManagementService.onFormClose($ctrl.uiState);
            $ctrl.utils.resetForm(formData);
        } else {
            const tableRowIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === $ctrl.uiState.selectedEntity.Id);
            if (tableRowIndex === -1) {
                $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
                throw new Error(`Entity not found in table`);
            }

            $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = $ctrl.utils.buildUpdatedEntityData(formData, $ctrl.uiState.selectedEntity);
            const hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(
                $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex]
            );
            $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = hydratedEntity;
            $ctrl.uiState.selectedEntityName = formData.name;
            $ctrl.utils.reselectEntityAfterUpdate({
                timeout: $ctrl.$timeout,
                rowIndex: tableRowIndex,
                formManagementService: $ctrl.formManagementService, 
                uiState: $ctrl.uiState,
                form: $ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form] 
            });
        }
    },
    null,
    () => { // onFinally
        $ctrl.uiState.isSaving = false;
    },
    $ctrl.uiState.currentTab.name,
    displayName,
    $ctrl.uiState.selectedEntity,
    additionalData
);

const entityName = $ctrl.uiState.selectedEntityName || "Item";

await $ctrl.entityOperationsService.confirmDelete($ctrl.uiState.selectedEntity, entityName)
    .then(confirmed => {
        if (!confirmed) return;

        $ctrl.uiState.isDeleting = true;

        return $ctrl.entityOperationsService.executeEntityOperation(
            "DELETE",           // Method
            null,               // No form data
            () => {             // Success
                $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
                $ctrl.uiState.selectedEntity = null;
            },
            null,               // Error
            () => {             // Finally
                $ctrl.uiState.isDeleting = false;
            },
            $ctrl.uiState.currentTab.name,       // EntityType
            entityName,         // Display Name
            $ctrl.uiState.selectedEntity
        );
    });

await $ctrl.baseGridControllerService.handleRowSelection($ctrl, row, {

    uiState: $ctrl.uiState,
    utils: $ctrl.utils,
    referenceService: $ctrl.referenceDataService,
    viewService: $ctrl.entityViewService,
    gridData: $ctrl.tabStore[$ctrl.uiState.currentTab.name]?.data

});

// Close form if user is not adding or editing
if ((!$ctrl.uiState.isCreatingNewEntity && $ctrl.uiState.isFormOpen) && (!$ctrl.uiState.isEditingExistingEntity && $ctrl.uiState.isFormOpen)) {
    $ctrl.formManagementService.onFormClose($ctrl.uiState)
}

if ($ctrl.uiState.currentTab.name === "earning" || $ctrl.uiState.currentTab.name === "benefit") {
    if (row) {
        $ctrl.loaders.loadPayComponentAssignments(row.Id, $ctrl.uiState.currentTab.name);
    }
}

const componentType = $ctrl.uiState.currentTab.name;
const componentId = $ctrl.uiState.selectedEntity?.Id;
const componentName = $ctrl.uiState.selectedEntity?.Name || "Component";

if (!componentId) {
    console.error("No component selected");
    return;
}

const isEarning = componentType === 'earning';
const isWorker = targetType === 'worker';

const stateRoot = $ctrl.uiState.assignments[componentType];
const currentList = stateRoot[targetType].current || [];

// 1. Structure the assigned rows map
const assignedItems = currentList.map(item => ({
    Id: item.Id,
    _linkId: item._linkId,
    Name: item.Name,
    CustomEmployeeAmount: item.CustomEmployeeAmount,
    ...(!isEarning && { CustomEmployerAmount: item.CustomEmployerAmount })
}));

const currentAssignedIds = assignedItems.map(x => x.Id);

// 2. Setup the static baseline filters
const commonQueryParams = !isWorker
    ? [`CompanyId=${$ctrl.globalSelectedCompany.companyId}`, "Active=1"]
    : ["Active=1", "WorkerId_isnotnull"];

// Apply Company Scoping for Workers
if (isWorker) {
    try {
        const companyWorkerIds = await $ctrl.workerService.getCompanyWorkerIds();
        const workerIdFilter = companyWorkerIds.length > 0 ? companyWorkerIds.join(",") : -1;
        commonQueryParams.push(`WorkerId_in=${workerIdFilter}`);
    } catch (error) {
        console.error("Failed to fetch company worker IDs:", error);
        // Fallback to empty state filter to block unauthorized data leaking
        commonQueryParams.push("WorkerId_in=-1");
    }
}

const exclusionQueryKey = isWorker ? 'WorkerId_notin' : 'Id_notin';
let preloadQueryParams = [...commonQueryParams];

if (currentAssignedIds.length > 0) {
    preloadQueryParams.push(`${exclusionQueryKey}=${currentAssignedIds.join(",")}`);
}

const fetchEntity = isWorker ? 'user' : 'position';
const mapUnassignedEntity = (e) => ({
    Id: isWorker ? e.WorkerId : e.Id,
    Name: isWorker ? `${e.FirstName} ${e.LastName}` : e.Title,
});

let unassignedItems = [];
let unassignedPageCount = 1;

try {
    // 3. Fire the initial baseline data pull
    const res = await $ctrl.payrollApiService.get({
        entity: fetchEntity,
        query: preloadQueryParams.join("&")
    });

    const entities = res.entities ?? res ?? [];
    unassignedItems = entities.map(mapUnassignedEntity);
    unassignedPageCount = res.metadata?.pageCount ?? 1;

    // 4. Build dynamic modal layout columns
    const entityColumns = isWorker
        ? [{ name: "Name", valueKey: "Name", enableEditing: false }]
        : [{ name: "Title", valueKey: "Name", enableEditing: false }];

    const amountColumns = [
        { name: "Custom Employee Amount", valueKey: "CustomEmployeeAmount", enableEditing: true, type: "number" }
    ];
    if (!isEarning) {
        amountColumns.push({ name: "Custom Employer Amount", valueKey: "CustomEmployerAmount", enableEditing: true, type: "number" });
    }

    const totalAssignedColumns = [...entityColumns, ...amountColumns];

    // 5. Hand execution over to the centralized helper method
    return $ctrl.assignmentUtilsService.openAssignmentModal({
        title: `Assign ${componentName} to ${isWorker ? "Workers" : "Positions"}`,
        assigned: {
            columns: totalAssignedColumns,
            items: assignedItems
        },
        unassigned: {
            columns: entityColumns,
            items: unassignedItems,
            totalPages: unassignedPageCount
        },
        api: {
            entity: fetchEntity,
            baseParams: commonQueryParams,
            searchParamKey: isWorker ? "FirstName_contains" : "Title_contains",
            searchProperty: "Name",
            searchPlaceholder: isWorker ? "First Name contains" : "Title contains",
            exclusionQueryKey: exclusionQueryKey,
            exclusionItemKey: "Id" // Tracks live row mappings automatically on changes
        },
        mapEntityFn: mapUnassignedEntity,
        onApply: (appliedItems) => {
            $ctrl.payComponentAssignmentService.syncPayComponentsByEarningOrBenefit(
                $ctrl.payrollApiService,
                targetType,
                componentType,
                componentId,
                stateRoot[targetType].original,
                appliedItems,
            ).then(() => {
                $ctrl.loaders.loadPayComponentAssignments(componentId, componentType);
            });
        }
    });

} catch (err) {
    console.warn("Skipping preload due to API limitation", err);
}
